verification_tests:
from target import same_point


def test_identical_points():
    assert same_point((1.0, 2.0), (1.0, 2.0)) is True


def test_clearly_different_points():
    assert same_point((1.0, 2.0), (3.0, 2.0)) is False


def test_binary_float_error_is_tolerated():
    assert same_point((0.1 + 0.2, 1.0), (0.3, 1.0)) is True
